  "faceGallery.listIdentities": "List the known face identities in the gallery.",
  "faceGallery.listIdentitySamples": "List the face samples assigned to an identity.",
  "faceGallery.listRecentFaces": "List recently detected faces, optionally for one or several cameras.",
  "faceGallery.moveIdentitySample": "Move an enrolled sample onto another person. The crop is re-owned, the source face keeps its link and follows (recognizedIdentityId), and an unknown person is refused.",
  "faceGallery.removeSample": "Remove one face sample from an identity.",
  "faceGallery.renameIdentity": "Rename a face identity.",
